window.docContents[135].resolve({"/rules/RG1006/#RG1006-rationale":{"contents":"A positive proof surface must consist of kernel-checked definitions. Unsafe and partial code can be executed, but it cannot serve as logical evidence, and reasoning about it silently depends on its runtime behavior.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1006: Unsafe and partial declarations require exact helper authentication","header":"Why it matters","id":"/rules/RG1006/#RG1006-rationale"},"/rules/RG2005/#RG2005-rationale":{"contents":"Successful elaboration alone is not checked admission: metaprograms and debug options can store declarations the kernel never checked. An accepted result must rest on kernel-checked evidence for the exact frozen sources.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2005: Required admission and source evidence must be complete","header":"Why it matters","id":"/rules/RG2005/#RG2005-rationale"},"/rules/RG4003/#RG4003-rationale":{"contents":"A negative example documents what Lean rejects. If it stops failing, or fails for another reason, the documentation claims a rejection that no longer holds.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4003: Negative examples require completed intended rejection","header":"Why it matters","id":"/rules/RG4003/#RG4003-rationale"},"/rules/RG5002/#RG5002-rationale":{"contents":"A material claim must be readable without reconstructing it from the proof: the docstring states what the declaration establishes and under which assumptions, and binds the written intent to that exact declaration.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5002: Registered public material declarations require docstrings","header":"Why it matters","id":"/rules/RG5002/#RG5002-rationale"}});